widget_def.init:
var root=container;
root.innerHTML='<div style="background:#0d0f14;font-family:system-ui,sans-serif;padding:12px;color:#e5e7eb;display:flex;flex-direction:column;gap:10px">'
+'<div style="font-weight:700;font-size:13px">⚙️ Interactions CYP450 — Substrat × Modulateur</div>'
+'<div style="background:#111827;border:1px solid rgba(58,176,158,.25);border-radius:8px;padding:10px">'
+'<div style="font-size:10px;color:#9ca3af;text-transform:uppercase">Effet sur l\'enzyme</div>'
+'<div id="cyp-tabs" style="display:flex;gap:5px;margin:6px 0;flex-wrap:wrap"></div>'
+'<div style="font-size:10px;color:#9ca3af;text-transform:uppercase;margin-top:6px">Intensité <span id="cyp-int-l" style="color:#3ab09e">modérée</span></div>'
+'<input type="range" id="cyp-int" min="1" max="3" value="2" step="1" style="width:100%;accent-color:#3ab09e">'
+'<div style="text-align:center;margin:10px 0">'
+'<div style="font-size:10px;color:#9ca3af">Concentration du substrat</div>'
+'<span id="cyp-out" style="font-size:26px;font-weight:800;color:#3ab09e">100%</span></div>'
+'<div id="cyp-bar" style="height:20px;border-radius:10px;background:#1f2937;overflow:hidden"><div id="cyp-fill" style="height:100%;width:50%;background:#3ab09e;transition:width .2s"></div></div>'
+'<div id="cyp-note" style="font-size:11px;margin-top:10px;padding:8px;border-radius:6px;line-height:1.5"></div>'
+'<div style="font-size:9px;color:#6b7280;margin-top:8px;line-height:1.5">Inhibiteur → ↑ substrat (risque surdosage/toxicité). Inducteur → ↓ substrat (risque inefficacité). Prodrogue : effet INVERSÉ (ex. codéine→morphine via CYP2D6).</div>'
+'</div></div>';
var mode='inhib', intensity=2, isProdrug=false;
var modes=[{k:'inhib',l:'🛑 Inhibiteur'},{k:'induc',l:'⚡ Inducteur'},{k:'prodrug',l:'💊 Prodrogue + inhib.'}];
function tabs(){root.querySelector('#cyp-tabs').innerHTML=modes.map(function(o){return '<button data-k="'+o.k+'" style="padding:5px 8px;border-radius:6px;border:1px solid '+(mode===o.k?'#3ab09e':'rgba(255,255,255,.15)')+';background:'+(mode===o.k?'rgba(58,176,158,.18)':'#1f2937')+';color:'+(mode===o.k?'#3ab09e':'#9ca3af')+';font-size:10px;cursor:pointer">'+o.l+'</button>';}).join('');
  root.querySelectorAll('#cyp-tabs button').forEach(function(b){b.addEventListener('click',function(){mode=b.getAttribute('data-k');tabs();calc();});});}
function calc(){
  intensity=+root.querySelector('#cyp-int').value;
  root.querySelector('#cyp-int-l').textContent=['faible','modérée','forte'][intensity-1];
  var factor=[1.5,3,6][intensity-1];
  var pct, note, col;
  if(mode==='inhib'){pct=Math.round(100*factor);note='🛑 L\'inhibiteur bloque le métabolisme → accumulation du substrat actif → risque de surdosage et toxicité.';col='#f87171';}
  else if(mode==='induc'){pct=Math.round(100/factor);note='⚡ L\'inducteur accélère le métabolisme → chute de concentration → risque d\'échec thérapeutique.';col='#fbbf24';}
  else{pct=Math.round(100/factor);note='💊 Prodrogue : l\'inhibiteur EMPÊCHE la bioactivation → MOINS de métabolite actif (ex. codéine + paroxétine sur CYP2D6 → analgésie réduite).';col='#60a5fa';}
  root.querySelector('#cyp-out').textContent=pct+'%';
  var fill=root.querySelector('#cyp-fill');
  fill.style.width=Math.min(100,pct/2)+'%';fill.style.background=col;
  var n=root.querySelector('#cyp-note');n.textContent=note;
  n.style.background=col.replace(')',',.13)').replace('#','rgba(').length?'rgba(255,255,255,.05)':'';
  n.style.background='rgba(255,255,255,.04)';n.style.color=col;
}
root.querySelector('#cyp-int').addEventListener('input',calc);
tabs();calc();
